-- Create "marketflow_permissions" table
CREATE TABLE "marketflow_permissions" ("id" uuid NOT NULL, "permission_code" character varying NOT NULL, "name" character varying NOT NULL, "module" character varying NOT NULL, "action" character varying NOT NULL, "resource" character varying NULL, "description" text NULL, "created_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- Create index "marketflow_permissions_permission_code_key" to table: "marketflow_permissions"
CREATE UNIQUE INDEX "marketflow_permissions_permission_code_key" ON "marketflow_permissions" ("permission_code");
-- Create index "marketflowpermission_action" to table: "marketflow_permissions"
CREATE INDEX "marketflowpermission_action" ON "marketflow_permissions" ("action");
-- Create index "marketflowpermission_module" to table: "marketflow_permissions"
CREATE INDEX "marketflowpermission_module" ON "marketflow_permissions" ("module");
-- Create index "marketflowpermission_module_action" to table: "marketflow_permissions"
CREATE INDEX "marketflowpermission_module_action" ON "marketflow_permissions" ("module", "action");
-- Create index "marketflowpermission_permission_code" to table: "marketflow_permissions"
CREATE UNIQUE INDEX "marketflowpermission_permission_code" ON "marketflow_permissions" ("permission_code");
-- Create "marketflow_roles" table
CREATE TABLE "marketflow_roles" ("id" uuid NOT NULL, "tenant_id" uuid NOT NULL, "role_code" character varying NOT NULL, "name" character varying NOT NULL, "description" text NULL, "is_system_role" boolean NOT NULL DEFAULT false, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- Create index "marketflowrole_is_system_role" to table: "marketflow_roles"
CREATE INDEX "marketflowrole_is_system_role" ON "marketflow_roles" ("is_system_role");
-- Create index "marketflowrole_tenant_id" to table: "marketflow_roles"
CREATE INDEX "marketflowrole_tenant_id" ON "marketflow_roles" ("tenant_id");
-- Create index "marketflowrole_tenant_id_role_code" to table: "marketflow_roles"
CREATE UNIQUE INDEX "marketflowrole_tenant_id_role_code" ON "marketflow_roles" ("tenant_id", "role_code");
-- Create "role_permissions" table
CREATE TABLE "role_permissions" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "role_id" uuid NOT NULL, "permission_id" uuid NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "role_permissions_marketflow_permissions_permission" FOREIGN KEY ("permission_id") REFERENCES "marketflow_permissions" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "role_permissions_marketflow_roles_role" FOREIGN KEY ("role_id") REFERENCES "marketflow_roles" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "rolepermission_permission_id" to table: "role_permissions"
CREATE INDEX "rolepermission_permission_id" ON "role_permissions" ("permission_id");
-- Create index "rolepermission_role_id" to table: "role_permissions"
CREATE INDEX "rolepermission_role_id" ON "role_permissions" ("role_id");
-- Create index "rolepermission_role_id_permission_id" to table: "role_permissions"
CREATE UNIQUE INDEX "rolepermission_role_id_permission_id" ON "role_permissions" ("role_id", "permission_id");
-- Create "marketflow_users" table
CREATE TABLE "marketflow_users" ("id" uuid NOT NULL, "tenant_id" uuid NOT NULL, "auth_service_user_id" uuid NOT NULL, "email" character varying NOT NULL, "status" character varying NOT NULL DEFAULT 'active', "sync_status" character varying NOT NULL DEFAULT 'synced', "last_sync_at" timestamptz NULL, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- Create index "marketflow_users_auth_service_user_id_key" to table: "marketflow_users"
CREATE UNIQUE INDEX "marketflow_users_auth_service_user_id_key" ON "marketflow_users" ("auth_service_user_id");
-- Create index "marketflowuser_auth_service_user_id" to table: "marketflow_users"
CREATE UNIQUE INDEX "marketflowuser_auth_service_user_id" ON "marketflow_users" ("auth_service_user_id");
-- Create index "marketflowuser_status" to table: "marketflow_users"
CREATE INDEX "marketflowuser_status" ON "marketflow_users" ("status");
-- Create index "marketflowuser_sync_status" to table: "marketflow_users"
CREATE INDEX "marketflowuser_sync_status" ON "marketflow_users" ("sync_status");
-- Create index "marketflowuser_tenant_id" to table: "marketflow_users"
CREATE INDEX "marketflowuser_tenant_id" ON "marketflow_users" ("tenant_id");
-- Create index "marketflowuser_tenant_id_auth_service_user_id" to table: "marketflow_users"
CREATE UNIQUE INDEX "marketflowuser_tenant_id_auth_service_user_id" ON "marketflow_users" ("tenant_id", "auth_service_user_id");
-- Create "user_role_assignments" table
CREATE TABLE "user_role_assignments" ("id" uuid NOT NULL, "tenant_id" uuid NOT NULL, "assigned_by" uuid NOT NULL, "assigned_at" timestamptz NOT NULL, "expires_at" timestamptz NULL, "marketflow_role_user_assignments" uuid NULL, "user_id" uuid NOT NULL, "role_id" uuid NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "user_role_assignments_marketflow_roles_role" FOREIGN KEY ("role_id") REFERENCES "marketflow_roles" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "user_role_assignments_marketflow_roles_user_assignments" FOREIGN KEY ("marketflow_role_user_assignments") REFERENCES "marketflow_roles" ("id") ON UPDATE NO ACTION ON DELETE SET NULL, CONSTRAINT "user_role_assignments_marketflow_users_user" FOREIGN KEY ("user_id") REFERENCES "marketflow_users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "userroleassignment_expires_at" to table: "user_role_assignments"
CREATE INDEX "userroleassignment_expires_at" ON "user_role_assignments" ("expires_at");
-- Create index "userroleassignment_role_id" to table: "user_role_assignments"
CREATE INDEX "userroleassignment_role_id" ON "user_role_assignments" ("role_id");
-- Create index "userroleassignment_tenant_id" to table: "user_role_assignments"
CREATE INDEX "userroleassignment_tenant_id" ON "user_role_assignments" ("tenant_id");
-- Create index "userroleassignment_tenant_id_user_id_role_id" to table: "user_role_assignments"
CREATE UNIQUE INDEX "userroleassignment_tenant_id_user_id_role_id" ON "user_role_assignments" ("tenant_id", "user_id", "role_id");
-- Create index "userroleassignment_user_id" to table: "user_role_assignments"
CREATE INDEX "userroleassignment_user_id" ON "user_role_assignments" ("user_id");
